#include <bits/stdc++.h>
using namespace std;

struct Node {
    char ch;
    int index;
    Node* nextArray[26];
    bool hasCul;
    bool isSame;
    int nextCount;
    vector<Node*> nextList;
    vector<long long> countArray;

    Node(char c, int i, int n) : ch(c), index(i), hasCul(false), isSame(false), nextCount(0), countArray(n, 0LL) {
        for (int j = 0; j < 26; j++) nextArray[j] = nullptr;
    }

    string toString() const {
        return string(1, ch);
    }

    void addNext(int idx, Node* node) {
        if (nextArray[idx] == nullptr) {
            nextCount++;
            nextArray[idx] = node;
            nextList.push_back(node);
        }
    }
};

static void find(Node* node) {
    if (node->hasCul) {
        return;
    }

    node->countArray[0]++;
    for (Node* next : node->nextList) {
        find(next);
        for (size_t i = 0; i < next->countArray.size(); i++) {
            if (next->countArray[i] > 0) {
                node->countArray[i + 1] += next->countArray[i];
            }
        }
    }

    node->hasCul = true;
}

class InputReader {
    istream& in;
public:
    InputReader(istream& stream) : in(stream) {}

    string next() {
        string s;
        in >> s;
        return s;
    }

    long long nextLong() { return stoll(next()); }
    int nextInt() { return stoi(next()); }
    double nextDouble() { return stod(next()); }
    float nextFloat() { return stof(next()); }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    InputReader inputReader(cin);

    int n = inputReader.nextInt();
    long long k = inputReader.nextLong();
    string str = inputReader.next();

    vector<bool> letters(26, false);
    vector<Node*> list;
    list.reserve(n);
    for (size_t i = 0; i < str.length(); i++) {
        char c = str[i];
        Node* node = new Node(c, (int)i, n);
        if (letters[c - 'a']) {
            node->isSame = true;
        } else {
            letters[c - 'a'] = true;
        }
        list.push_back(node);
    }
    for (size_t i = 0; i < list.size(); i++) {
        Node* ai = list[i];
        for (size_t j = i + 1; j < list.size(); j++) {
            Node* aj = list[j];
            ai->addNext(aj->ch - 'a', aj);
        }
    }

    for (Node* node : list) {
        find(node);
    }

    vector<long long> totalCountArray(n, 0LL);
    for (int i = 0; i < n; i++) {
        for (Node* node : list) {
            if (!node->isSame) {
                totalCountArray[i] += node->countArray[i];
            }
        }
    }

    long long totalCost = 0LL;
    long long selectCount = 0LL;
    for (int i = n - 1; i >= 0; i--) {
        if (selectCount + totalCountArray[i] < k) {
            totalCost += (long long)(n - 1 - i) * totalCountArray[i];
            selectCount += totalCountArray[i];
        } else {
            long long over = (selectCount + totalCountArray[i]) - k;
            totalCost += (long long)(n - 1 - i) * (totalCountArray[i] - over);
            selectCount += (totalCountArray[i] - over);
            break;
        }
    }

    if (selectCount < k) {
        if (selectCount == k - 1) {
            cout << (totalCost + n) << endl;
        } else {
            cout << -1 << endl;
        }
    } else {
        cout << totalCost << endl;
    }

    return 0;
}
